49: const TOTAL_COUNT_FIELDS = ['totalCount', 'total', 'totalNum', 'allCount', 'rowCount']
50: const FAIL_COUNT_FIELDS = ['failCount', 'failedCount', 'failureCount', 'errorCount', 'failNum', 'errorNum']
51: const RESULT_FILE_FIELDS = [
52:   'errorFile',
53:   'errorFileUrl',
54:   'errorFilePath',
55:   'failFile',
56:   'failFileUrl',
57:   'failFilePath',
