66: export default {
67:   name: 'ZsImport',
68:   props: {
69:     headers: {
70:       type: Object,
71:       default: function () {
72:         return {}
73:       }
74:     },
75:     uploadData: {
76:       type: Object,
77:       default: function () {
78:         return {}
79:       }
80:     },
81:     url: {
82:       type: String,
83:       required: false
84:     },
85:     loadingText: {
86:       type: String,
87:       default: '数据正在导入中，导入完成前，请不要关闭弹窗'
88:     },
89:     disabled: {
90:       type: Boolean,
91:       default: false
92:     },
93:     tmpl: {
94:       type: Boolean,
95:       default: true
96:     },
97:     autoClose: {
98:       type: Boolean,
99:       default: true
100:     },
101:     responseType: {
102:       type: String,
103:       default: ''
104:     },
105:     resultFileName: {
106:       type: String,
107:       default: '导入校验结果.xlsx'
108:     },
109:     showImportResult: {
110:       type: Boolean,
111:       default: false
112:     }
113:   },
114:   data() {
115:     return {
116:       fileList: [],
117:       loading: false,
118:       importResult: null
119:     }
120:   },
121:   computed: {
122:     uploadHeaders() {
123:       return { Authorization: 'Bearer ' + getToken(), ...this.headers }
124:     },
125:     uploadUrl() {
126:       return import.meta.env.VITE_APP_BASE_API + '' + this.url
127:     },
128:     hasResultCounts() {
129:       return this.importResult?.totalCount !== undefined && this.importResult?.failCount !== undefined
130:     },
131:     hasResultFile() {
132:       return this.importResult?.file instanceof Blob || !!this.importResult?.fileUrl
133:     }
134:   },
135:   methods: {
136:     // 文件上传中处理
137:     handleFileUploadProgress(event, file, fileList) {
138:       this.loading = true
139:     },
140:     handleChange(file, fileList) {
141:       if (fileList.length > 1) {
142:         fileList.splice(0, 1)
143:       }
144:     },
145:     // 文件上传成功处理
146:     handleFileSuccess(response, file, fileList) {
147:       this.loading = false
148:       if ((response.code || 200) == 200) {
149:         this.msgSuccess(response.msg || '导入成功')
150:         this.$emit('refresh', { file: file.raw, ...response })
151:         this.autoClose && this.close()
152:       } else {
153:         if (this.showImportResult) {
154:           this.setImportResult(response)
155:         } else {
156:           this.msgError(response.msg || '文件导入错误')
157:         }
158:         this.$emit('error', response)
159:       }
160:     },
161:     handleError(err) {
162:       this.loading = false
163:       // 尝试从不同层级获取错误信息
164:       let errorMessage = '文件导入失败'
165:       try {
166:         errorMessage = JSON.parse(err.message).msg || errorMessage
167:       } catch (error) {}
168:       this.msgError(errorMessage)
169:     },
170:     // 提交上传文件
171:     submitFileForm() {
172:       if (this.importResult) {
173:         this.close()
174:         return
175:       }
176:       this.$emit('before-upload')
177:       if (this.responseType === 'blob') {
178:         this.submitBlobFileForm()
179:         return
180:       }
181:       this.$refs.upload.submit()
182:     },
183:     submitBlobFileForm() {
184:       const uploadFile = this.$refs.upload.uploadFiles[0]
185:       if (!uploadFile?.raw) {
186:         this.msgError('请选择需要导入的文件')
187:         return
188:       }
189: 
190:       const formData = new FormData()
191:       Object.keys(this.uploadData || {}).forEach((key) => {
192:         formData.append(key, this.uploadData[key])
193:       })
194:       formData.append('file', uploadFile.raw)
195: 
196:       this.loading = true
197:       this.$post(this.url, formData, {
198:         responseType: 'blob',
199:         noMessage: true,
200:         returnRawResponse: this.showImportResult
201:       })
202:         .then((res) => this.handleBlobResponse(res, uploadFile))
203:         .catch((error) => this.handleBlobError(error))
204:         .finally(() => {
205:           this.loading = false
206:         })
207:     },
208:     handleBlobResponse(res, file) {
209:       const response = res?.data !== undefined && res?.headers ? res.data : res
210:       const headers = res?.headers || {}
211: 
212:       if (!(response instanceof Blob)) {
213:         this.handleFileSuccess(response, file, [])
214:         return
215:       }
216: 
217:       if (this.isExcelBlob(response)) {
218:         this.handleImportResultFile(response, headers)
219:         return
220:       }
221: 
222:       this.readBlobText(response).then((text) => {
223:         const parsedResponse = JSON.parse(text)
224:         if ((parsedResponse.code || 200) == 200) {
225:           const successCount = parsedResponse.data !== undefined
226:             && parsedResponse.data !== null
227:             && parsedResponse.data !== ''
228:             && !Number.isNaN(Number(parsedResponse.data))
229:             ? Number(parsedResponse.data)
230:             : this.getResultNumber(
231:               [parsedResponse.data, parsedResponse],
232:               ['successCount', 'count', 'totalCount', 'total']
233:             )
234:           const message = successCount !== undefined
235:             ? `导入成功，共导入${successCount}条`
236:             : (parsedResponse.msg || '导入成功')
237:           this.msgSuccess(message)
238:           this.$emit('refresh', { file: file.raw, ...parsedResponse })
239:           this.autoClose && this.close()
240:         } else {
241:           if (this.showImportResult) {
242:             this.setImportResult(parsedResponse, { headers })
243:           } else {
244:             this.msgError(parsedResponse.msg || '文件导入错误')
245:           }
246:           this.$emit('error', parsedResponse)
247:         }
248:       }).catch(() => {
249:         this.handleImportResultFile(response, headers)
250:       })
251:     },
252:     handleBlobError(error) {
253:       const blob = error?.response?.data
254:       if (blob instanceof Blob) {
255:         if (blob.type && blob.type.includes('json')) {
256:           this.readBlobText(blob).then((text) => {
257:             const response = JSON.parse(text)
258:             if (this.showImportResult) {
259:               this.setImportResult(response, { headers: error?.response?.headers })
260:             } else {
261:               this.msgError(response.msg || '文件导入失败')
262:             }
263:           }).catch(() => {
264:             this.msgError('文件导入失败')
265:           })
266:         } else {
267:           this.handleImportResultFile(blob, error?.response?.headers)
268:         }
269:         return
270:       }
271:       this.msgError(error?.message || '文件导入失败')
272:     },
273:     isExcelBlob(blob) {
274:       return blob.type && (
275:         blob.type.includes('spreadsheet') ||
276:         blob.type.includes('excel')
277:       )
278:     },
279:     handleImportResultFile(blob, headers = {}) {
280:       if (this.showImportResult) {
281:         this.setImportResult({}, { file: blob, headers })
282:         this.$emit('error', blob)
283:         return
284:       }
285:       this.downloadImportResult(blob)
286:     },
287:     downloadImportResult(blob) {
288:       downloadBlobFile(blob, this.resultFileName)
289:       this.msgError(`导入校验未通过，已下载${this.resultFileName}`)
290:       this.$emit('error', blob)
291:     },
292:     setImportResult(response = {}, options = {}) {
293:       const resultData = response?.data && typeof response.data === 'object' && !(response.data instanceof Blob)
294:         ? response.data
295:         : {}
296:       const sources = [resultData, response]
297:       const message = response.msg || response.message || resultData.msg || resultData.message
298:       const parsedCounts = this.parseCountsFromMessage(message)
299:       this.importResult = {
300:         totalCount: this.getResultNumber(sources, TOTAL_COUNT_FIELDS)
301:           ?? this.getHeaderNumber(options.headers, ['x-total-count', 'total-count', 'totalcount', 'x-import-total-count', 'import-total-count', 'x-total', 'total'])
302:           ?? parsedCounts.totalCount,
303:         failCount: this.getResultNumber(sources, FAIL_COUNT_FIELDS)
304:           ?? this.getHeaderNumber(options.headers, ['x-fail-count', 'fail-count', 'failcount', 'failed-count', 'failedcount', 'x-error-count', 'error-count', 'errorcount', 'x-import-fail-count', 'import-fail-count', 'import-error-count', 'x-fail'])
305:           ?? parsedCounts.failCount,
306:         file: options.file || (response.data instanceof Blob ? response.data : undefined),
307:         fileUrl: this.getResultFileUrl(response),
308:         message
309:       }
310:     },
311:     getResultNumber(sources, fields) {
312:       for (const source of sources) {
313:         if (!source || typeof source !== 'object') continue
314:         for (const field of fields) {
315:           const value = source[field]
316:           if (value !== undefined && value !== null && value !== '' && !Number.isNaN(Number(value))) {
317:             return Number(value)
318:           }
319:         }
320:       }
321:       return undefined
322:     },
323:     getHeaderNumber(headers = {}, fields) {
324:       const normalizedHeaders = Object.keys(headers || {}).reduce((result, key) => {
325:         result[String(key).toLowerCase()] = headers[key]
326:         return result
327:       }, {})
328:       for (const field of fields) {
329:         const value = normalizedHeaders[field]
330:         if (value !== undefined && value !== null && value !== '' && !Number.isNaN(Number(value))) {
331:           return Number(value)
332:         }
333:       }
334:       return undefined
335:     },
336:     parseCountsFromMessage(message = '') {
337:       const text = String(message || '')
338:       const totalMatch = text.match(/共\s*(\d+)\s*条/)
339:       const failMatch = text.match(/(?:其中\s*)?(\d+)\s*条[^，。；]*?(?:校验失败|失败)/)
340:       return {
341:         totalCount: totalMatch ? Number(totalMatch[1]) : undefined,
342:         failCount: failMatch ? Number(failMatch[1]) : undefined
343:       }
344:     },
345:     getResultFileUrl(response = {}) {
346:       const resultData = response?.data && typeof response.data === 'object' && !(response.data instanceof Blob)
347:         ? response.data
348:         : {}
349:       const sources = [resultData, response]
350:       if (typeof response.data === 'string' && response.data.trim()) {
351:         return response.data.trim()
352:       }
353:       for (const source of sources) {
354:         for (const field of RESULT_FILE_FIELDS) {
355:           if (typeof source?.[field] === 'string' && source[field].trim()) {
356:             return source[field].trim()
357:           }
358:         }
359:       }
360:       return undefined
361:     },
362:     downloadResultFile() {
363:       if (this.importResult?.file instanceof Blob) {
364:         downloadBlobFile(this.importResult.file, this.resultFileName)
365:         return
366:       }
367:       if (!this.importResult?.fileUrl) return
368:       this.$get(this.importResult.fileUrl, {}, {
369:         responseType: 'blob',
370:         noMessage: true
371:       }).then((blob) => {
372:         downloadBlobFile(blob, this.resultFileName)
373:       }).catch(() => {
374:         this.msgError('文件下载失败')
375:       })
376:     },
377:     readBlobText(blob) {
378:       return new Promise((resolve, reject) => {
379:         const reader = new FileReader()
380:         reader.onload = () => resolve(reader.result)
381:         reader.onerror = reject
382:         reader.readAsText(blob)
383:       })
384:     },
385:     close() {
386:       this.$emit('update:visible', false)
387:     },
388:     onClose() {
389:       this.importResult = null
390:       this.$refs.upload?.clearFiles()
391:     }
392:   }
393: }
